if (S.resources.mp.value >= 20) {
    await actor.applyHealing({ healer: actor,  amount: -20, type: "mp", showScrolling: true });
    const eff = thisItem.effects.getName("回溯").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, eff);

    const msg = `<div class="xjzl-chat-card"><div style="padding:4px 8px; border-left:4px solid #00ffff; background:rgba(0, 255, 255, 0.1); margin-left:2px;"><i class="fas fa-history"></i> <b>王氏易书：</b>消耗 20 点内力，获得 [回溯] 状态！</div></div>`;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}

const eff = thisItem.effects.getName("易理(初阶)").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);
const msg = `<div class="xjzl-chat-card"><div style="padding:4px 8px; border-left:4px solid #f39c12; background:rgba(243, 156, 18, 0.1); margin-left:2px;"><i class="fas fa-sun"></i> <b>易理天问：</b>已自动为自身施加 [易理(初阶)]。请手动为周围 <b>3米</b> 范围内的队友添加此状态！</div></div>`;
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });

const eff = thisItem.effects.getName("易理(初阶)").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);
const msg = `<div class="xjzl-chat-card"><div style="padding:4px 8px; border-left:4px solid #f39c12; background:rgba(243, 156, 18, 0.1); margin-left:2px;"><i class="fas fa-sun"></i> <b>易理天问：</b>已自动为自身施加 [易理(初阶)]。请手动为周围 <b>10米</b> 范围内的队友添加此状态！</div></div>`;
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });

const eff = thisItem.effects.getName("易理(高阶)").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);
const msg = `<div class="xjzl-chat-card"><div style="padding:4px 8px; border-left:4px solid #e67e22; background:rgba(230, 126, 34, 0.1); margin-left:2px;"><i class="fas fa-sun"></i> <b>易理天问：</b>已自动为自身施加 [易理(高阶)]。请手动为周围 <b>20米</b> 范围内的队友添加此状态！</div></div>`;
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });

if (["waigong", "neigong"].includes(args.type) && S.combat.blockTotal > 0) {
    await actor.applyHealing({ healer: actor,  amount: 5, type: "hp", showScrolling: true });
    const msg = `<div class="xjzl-chat-card"><div style="padding:4px 8px; border-left:4px solid #27ae60; background:rgba(39, 174, 96, 0.1); margin-left:2px;"><i class="fas fa-shield-alt"></i> <b>丹珠尔：</b>格挡成功，恢复 <span style="color:green; font-weight:bold;">5</span> 气血。</div></div>`;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}

if (!args.attacker || args.attacker.uuid === actor.uuid) return;
if (!["waigong", "neigong"].includes(args.type)) return;

// 1. 获取准确的原始伤害(已包含暴击)
const rawDmg = (args.isCrit && args.config.applyCritDamage) ? args.baseDamage * 2 : args.baseDamage;

// 2. 准确获取当前生效的格挡值
let blockVal = 0;
if (!args.config.ignoreBlock) {
    let total = S.combat.blockTotal || 0;
    if (args.config.ignoreStance) total = Math.max(0, total - (S.combat.stanceBlockValue || 0));
    blockVal = total;
}

// 3. 计算并暂存反伤值 (Min(格挡, 原始伤害-1))
if (blockVal > 0) {
    args.config._xuejingReflect = Math.max(0, Math.min(blockVal, rawDmg - 1));
    args.config._xuejingType = args.type;
}

const reflectDmg = args.config._xuejingReflect || 0;
if (reflectDmg <= 0) return;
if (actor.isReceivingReflection) return;

args.attacker.isReceivingReflection = true;
try {
    await args.attacker.applyDamage({ amount: reflectDmg, type: args.config._xuejingType, attacker: actor, isHit: true });
    const typeStr = args.config._xuejingType === 'waigong' ? '外功' : '内功';
    const cardHtml = `<div class="xjzl-chat-card"><div style="padding:4px 8px; border-left:4px solid #8b0000; background:rgba(139, 0, 0, 0.1); margin-left:2px;"><i class="fas fa-burn"></i> <b>藏边血经：</b>格挡反震！对攻击者反弹 <span style="color:red; font-weight:bold;">${reflectDmg}</span> 点${typeStr}伤害！</div></div>`;
    ChatMessage.create({speaker: ChatMessage.getSpeaker({actor: actor}), content: cardHtml});
} finally {
    args.attacker.isReceivingReflection = false;
}

if (!args.attacker || args.attacker.uuid === actor.uuid) return;
if (!["waigong", "neigong"].includes(args.type)) return;

// 1. 获取准确的原始伤害
const rawDmg = (args.isCrit && args.config.applyCritDamage) ? args.baseDamage * 2 : args.baseDamage;

// 2. 准确获取当前生效的格挡值与防御值
let blockVal = 0;
if (!args.config.ignoreBlock) {
    let total = S.combat.blockTotal || 0;
    if (args.config.ignoreStance) total = Math.max(0, total - (S.combat.stanceBlockValue || 0));
    blockVal = total;
}

let defVal = 0;
if (!args.config.ignoreDefense) {
    defVal = (args.type === "waigong") ? (S.combat.defWaigongTotal || 0) : (S.combat.defNeigongTotal || 0);
}

const maxReflect = blockVal + defVal;

// 3. 计算并暂存反伤值
if (maxReflect > 0) {
    args.config._xuejingReflect = Math.max(0, Math.min(maxReflect, rawDmg - 1));
    args.config._xuejingType = args.type;
}

const reflectDmg = args.config._xuejingReflect || 0;
if (reflectDmg <= 0) return;
if (actor.isReceivingReflection) return;

args.attacker.isReceivingReflection = true;
try {
    await args.attacker.applyDamage({ amount: reflectDmg, type: args.config._xuejingType, attacker: actor, isHit: true });
    const typeStr = args.config._xuejingType === 'waigong' ? '外功' : '内功';
    const cardHtml = `<div class="xjzl-chat-card"><div style="padding:4px 8px; border-left:4px solid #8b0000; background:rgba(139, 0, 0, 0.1); margin-left:2px;"><i class="fas fa-burn"></i> <b>藏边血经：</b>护体反震！对攻击者反弹 <span style="color:red; font-weight:bold;">${reflectDmg}</span> 点${typeStr}伤害！</div></div>`;
    ChatMessage.create({speaker: ChatMessage.getSpeaker({actor: actor}), content: cardHtml});
} finally {
    args.attacker.isReceivingReflection = false;
}

const hpPct = S.resources.hp.value / S.resources.hp.max;
if (hpPct > 0.3 && args.move && (args.move.type !== "basic" || args.move.id === 'opportunity-attack')) {
    const myMp = S.resources.mp.value;
    const targetMp = args.target.system?.resources?.mp?.value || 0;
    const diff = myMp - targetMp;
    if (diff >= 50) {
        const bonus = Math.floor(diff / 50) * 10;
        args.config.amount += bonus;

        const msg = `<div class="xjzl-chat-card"><div style="padding:4px 8px; border-left:4px solid #d35400; background:rgba(211, 84, 0, 0.1); margin-left:2px;"><i class="fas fa-fire-alt"></i> <b>暖乐：</b>内力深厚，招式伤害激增 <span style="color:#d35400; font-weight:bold;">${bonus}</span> 点！</div></div>`;
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
    }
}

const hpPct = S.resources.hp.value / S.resources.hp.max;
if (hpPct > 0.3 && args.move && (args.move.type !== "basic" || args.move.id === 'opportunity-attack')) {
    const myMp = S.resources.mp.value;
    const targetMp = args.target.system?.resources?.mp?.value || 0;
    const diff = myMp - targetMp;
    if (diff >= 50) {
        const bonus = Math.floor(diff / 50) * 10;
        args.config.amount += bonus;

        const msg = `<div class="xjzl-chat-card"><div style="padding:4px 8px; border-left:4px solid #d35400; background:rgba(211, 84, 0, 0.1); margin-left:2px;"><i class="fas fa-fire-alt"></i> <b>暖乐：</b>内力深厚，招式伤害激增 <span style="color:#d35400; font-weight:bold;">${bonus}</span> 点！</div></div>`;
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
    }
}

const hpPct = S.resources.hp.value / S.resources.hp.max;
if (hpPct > 0.3 && args.move && (args.move.type !== "basic" || args.move.id === 'opportunity-attack')) {
    const myMp = S.resources.mp.value;
    const targetMp = args.target.system?.resources?.mp?.value || 0;
    const diff = myMp - targetMp;
    if (diff >= 50) {
        const bonus = Math.floor(diff / 50) * 10;
        args.config.amount += bonus;

        const msg = `<div class="xjzl-chat-card"><div style="padding:4px 8px; border-left:4px solid #d35400; background:rgba(211, 84, 0, 0.1); margin-left:2px;"><i class="fas fa-fire-alt"></i> <b>暖乐：</b>内力深厚，招式伤害激增 <span style="color:#d35400; font-weight:bold;">${bonus}</span> 点！</div></div>`;
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
    }
}
